#### Step 3: Design Module Interfaces

Define clear contracts for how micro-frontends interact:

**Module Entry Point:**

Each micro-frontend exports a well-defined entry point:

```typescript
// enterprise-claims-mfe/src/index.tsx
export const mount = (container: HTMLElement, context: MfeContext) => {
  // Mount React app into container with provided context
  const root = ReactDOM.createRoot(container);
  root.render(
    <ClaimsApp
      user={context.user}
      apiBaseUrl={context.apiBaseUrl}
      onNavigate={context.navigation.onNavigate}
    />
  );

  return () => root.unmount(); // Cleanup function
};

export const routes = [
  '/claims',
  '/claims/:claimId',
  '/claims/:claimId/appeals',
];
```

**Context Interface:**

Shell provides standardized context to all micro-frontends:

```typescript
interface MfeContext {
  user: User;                    // Current authenticated user
  apiBaseUrl: string;            // Backend API base URL
  navigation: {
    onNavigate: (path: string) => void;  // Navigate to another route
    currentPath: string;                 // Current route path
  };
  events: EventBus;              // Cross-module event communication
  theme: Theme;                  // Design system theme configuration
}
```

