[patterns/application/micro-frontend/PTN-APP-MFE-002-micro-frontend-boundaries-pattern.md#phi-protection-across-module-boundaries]

### PHI Protection Across Module Boundaries

**HIPAA Security Rule Compliance:**

Micro-frontend boundaries introduce unique risks for Protected Health Information (PHI) leakage through shared contexts, event buses, and browser storage. Each module must implement PHI isolation patterns.

**Cross-Module PHI Protection Requirements:**

1. **No PHI in Shared State**: Shell-provided props, shared context, and event bus payloads must NEVER contain PHI
2. **Opaque Identifiers**: Cross-module communication uses non-PHI identifiers (claim_id, member_id) only—never names, dates of birth, SSNs
3. **Isolated PHI Fetching**: Each module fetches PHI directly from backend APIs at runtime—never through module-to-module communication
4. **Memory Cleanup**: Modules clear PHI from memory on unmount and logout
5. **No PHI in Bundles**: Build-time validation ensures PHI never embedded in JavaScript bundles
6. **Session Timeout**: 15-minute inactivity timeout across all modules (HIPAA requirement)

**Prohibited PHI Sharing Patterns:**

❌ **NEVER**: Pass PHI through Event Bus
```typescript
// FORBIDDEN: PHI in event payload
eventBus.publish('member.selected', {
  memberId: '12345',
  firstName: 'John',        // PHI!
  lastName: 'Doe',          // PHI!
  dateOfBirth: '1980-01-01' // PHI!
});
```

✅ **CORRECT**: Use opaque identifiers only
```typescript
// Safe: Only non-PHI identifier
eventBus.publish('member.selected', {
  memberId: '12345' // Opaque identifier—each module fetches PHI independently
});
```

❌ **NEVER**: Store PHI in Shared Context
```typescript
// FORBIDDEN: PHI in shared context
const MfeContext = {
  user: {
    userId: 'user-123',
    currentMember: {
      memberId: '12345',
      name: 'John Doe' // PHI in shared context!
    }
  }
};
```

✅ **CORRECT**: Each module fetches PHI independently
```typescript
// Safe: Only user identity in shared context
const MfeContext = {
  user: {
    userId: 'user-123',
    roles: ['claims_adjudicator']
  }
};

// Each module fetches PHI from backend
const memberDetails = await fetchMemberDetails(memberId); // PHI stays in module scope
```

**PHI Isolation Architecture:**

```typescript
// shell-application/src/context/MfeContext.ts
export interface MfeContext {
  user: {
    userId: string;           // Safe: User identity
    roles: string[];          // Safe: Authorization
    email: string;            // Safe: User contact
  };
  config: {
    apiBaseUrl: string;       // Safe: Configuration
    stateCode: string;        // Safe: Non-PHI context
  };
  events: EventBus;           // Must validate: No PHI in events
  navigation: NavigationAPI;  // Safe: Routing
}

// PHI stays within module boundaries
// claims-mfe/src/hooks/useMemberPHI.ts
const useMemberPHI = (memberId: string) => {
  const [phi, setPhi] = useState<MemberPHI | null>(null);

  useEffect(() => {
    // Fetch PHI directly from backend—never from shared context
    fetchMemberPHI(memberId).then(setPhi);

    // Cleanup: Clear PHI on unmount
    return () => setPhi(null);
  }, [memberId]);

  return phi; // PHI never leaves module scope
};
```

**Session Timeout Coordination:**

```typescript
// shell-application/src/security/SessionManager.ts
class SessionManager {
  private timeoutId: number | null = null;
  private readonly TIMEOUT_MS = 15 * 60 * 1000; // 15 minutes (HIPAA)

  resetTimeout() {
    if (this.timeoutId) clearTimeout(this.timeoutId);

    this.timeoutId = setTimeout(() => {
      // Notify all modules to clear PHI
      eventBus.publish('session.timeout', {});

      // Clear shared state
      this.clearSharedState();

      // Redirect to login
      window.location.href = '/logout';
    }, this.TIMEOUT_MS);
  }

  clearSharedState() {
    sessionStorage.clear();
    localStorage.removeItem('auth_token');
  }
}

// claims-mfe/src/hooks/useSessionTimeout.ts
const useSessionTimeout = (eventBus: EventBus) => {
  useEffect(() => {
    const handler = () => {
      // Clear PHI from module state
      clearAllPHI();
    };

    eventBus.subscribe('session.timeout', handler);
    return () => eventBus.unsubscribe('session.timeout', handler);
  }, [eventBus]);
};
```

**Build-Time PHI Detection:**

```javascript
// webpack.config.js - PHI Detection Plugin
const PHIDetectionPlugin = {
  apply(compiler) {
    compiler.hooks.emit.tapAsync('PHIDetectionPlugin', (compilation, callback) => {
      const phiPatterns = [
        /ssn["']?\s*:\s*["']\d{3}-\d{2}-\d{4}/, // SSN patterns
        /dateOfBirth["']?\s*:\s*["']\d{4}-\d{2}-\d{2}/, // DOB
        /medicalRecordNumber/i,
      ];

      for (const filename in compilation.assets) {
        const source = compilation.assets[filename].source();

        for (const pattern of phiPatterns) {
          if (pattern.test(source)) {
            compilation.errors.push(
              new Error(`PHI detected in bundle ${filename}! PHI must never be embedded in bundles.`)
            );
          }
        }
      }

      callback();
    });
  }
};
```

**Audit Logging Across Modules:**

```typescript
// shell-application/src/audit/AuditLogger.ts
class AuditLogger {
  logPHIAccess(event: PHIAccessEvent) {
    // Centralized audit logging for all modules
    fetch('/api/audit/phi-access', {
      method: 'POST',
      body: JSON.stringify({
        timestamp: new Date().toISOString(),
        userId: event.userId,
        moduleId: event.moduleId,         // Which MFE accessed PHI
        resourceType: event.resourceType, // 'member', 'claim', 'provider'
        resourceId: event.resourceId,     // Opaque identifier
        action: event.action,             // 'view', 'update', 'delete'
        ipAddress: event.ipAddress,
        userAgent: navigator.userAgent
      })
    });
  }
}

// claims-mfe/src/services/ClaimsService.ts
const fetchClaim = async (claimId: string, auditLogger: AuditLogger) => {
  const claim = await fetch(`/api/claims/${claimId}`);

  // Log PHI access from this module
  auditLogger.logPHIAccess({
    userId: currentUser.id,
    moduleId: 'claims-mfe',
    resourceType: 'claim',
    resourceId: claimId,
    action: 'view'
  });

  return claim;
};
```

